 * resolution needs the whole roster: `listMembers` pages newest-first, so the
 * longest-standing members sit beyond the first page.
 */
export async function listActiveMembersWithUsers(
  orgId: OrgId,
): Promise<readonly MemberWithUser[]> {
  const rows = getDb()
    .select({ member: members, user: users })
    .from(members)
    .innerJoin(users, eq(users.id, members.userId))
    .where(
      and(
        orgPredicate(members.orgId, orgId),
        eq(members.status, "active"),
        liveMemberPredicate(),
      ),
    )
    .all();

  return rows.map((row) => ({
    ...toMember(row.member),
    user: toUser(row.user),
  }));
}

