    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  };
}

/** The author of the comment that `commentId` answers, or `null` for a top-level comment. */
async function answeredAuthorId(
  orgId: OrgId,
  commentId: CommentId,
): Promise<UserId | null> {
  const reply = await commentRepo.findCommentById(orgId, commentId);
  if (!reply?.parentId) return null;

  const parent = await commentRepo.findCommentById(orgId, reply.parentId);
  return parent?.authorId ?? null;
}

