vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { consumeRateLimit } from "@/lib/rate-limit";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as commentService from "@/server/services/comment-service";
import * as issueService from "@/server/services/issue-service";
import * as notificationService from "@/server/services/notification-service";
import * as searchService from "@/server/services/search-service";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { Unsubscribe } from "@/types/event";

let cleanup: () => void;
let detach: Unsubscribe;
let tenant: Tenant;
let other: Tenant;
const ids: Record<string, string> = {};

async function addMember(orgId: string, email: string, name: string): Promise<string> {
  const user = await userRepo.insertUser({ email, name, passwordHash: "seed" });
  await memberRepo.insertMember(orgId as never, user.id, "member", null);
  return user.id;
}

async function alertKinds(recipientId: string, issueId: string): Promise<string[]> {
  const page = await notificationService.listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: recipientId as never,
    unreadOnly: false,
    kind: ["comment_created", "comment_mention"],
    limit: 100,
    cursor: null,
  });
  return page.items
    .filter((n) => n.href === `/issues/${issueId}`)
    .map((n) => n.kind)
    .sort();
}

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detach = searchService.registerSearchListeners();
  tenant = await createTenant("scratch", "growth");
  other = await createTenant("elsewhere", "growth");

  ids.shared = await addMember(tenant.org.id, "member@scratch-shared.test", "Shared Member");
  ids.long = await addMember(tenant.org.id, `${"a".repeat(64)}@scratch-long.test`, "Long");
  ids.plus = await addMember(tenant.org.id, "jo+tag@scratch-plus.test", "Plus");
  ids.one = await addMember(tenant.org.id, "x@scratch-one.test", "One");
  for (let i = 1; i <= 130; i += 1) {
    const n = String(i).padStart(4, "0");
    ids[`bulk${n}`] = await addMember(tenant.org.id, `bulk${n}@scratch-bulk.test`, `Bulk ${n}`);
  }
});

afterAll(() => {
  detach();
  cleanup();
});

describe("scratch: mentions", () => {
  it("resolves every active member, old ones included, and only this org's", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Mentions scale" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: `ping @owner @viewer @bulk0001 @x @jo+tag @member @${"a".repeat(64)} @admin`,
      parentId: null,
      mentionedUserIds: [],
    });

    expect(new Set(comment.mentionedUserIds)).toEqual(
      new Set([
        tenant.userIds.owner,
        tenant.userIds.viewer,
        tenant.userIds.admin,
        ids.bulk0001,
        ids.one,
        ids.plus,
        ids.long,
        ids.shared,
      ]),
    );
    expect(comment.mentionedUserIds).not.toContain(tenant.userIds.member);
    expect(comment.mentionedUserIds).not.toContain(other.userIds.admin);
  });

  it("does not mention a member of another workspace with the same handle", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Other workspace" }),
    );
    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "only @admin here",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(comment.mentionedUserIds).toEqual([tenant.userIds.admin]);
  });

  it("ignores a mention of the author's own handle and mentions in code", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Self and code" }),
    );
    const comment = await commentService.createComment(tenant.actors.owner, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "me @owner, not `@admin` and not a@b.test",
      parentId: null,
      mentionedUserIds: [],
    });
    expect(comment.mentionedUserIds).toEqual([]);
  });
});

describe("scratch: alerts", () => {
  it("alerts author, assignee and mentions once each, mention winning", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        title: "Alerts",
        assigneeId: tenant.userIds.admin,
      }),
    );
    await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "hey @admin and @viewer",
      parentId: null,
      mentionedUserIds: [],
    });

    expect(await alertKinds(tenant.userIds.admin, issue.id)).toEqual(["comment_mention"]);
    expect(await alertKinds(tenant.userIds.viewer, issue.id)).toEqual(["comment_mention"]);
    expect(await alertKinds(tenant.userIds.owner, issue.id)).toEqual(["comment_created"]);
    expect(await alertKinds(tenant.userIds.member, issue.id)).toEqual([]);
  });

  it("alerts the answered author; a mention outranks the reply alert", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Replies" }),
    );
    const top = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "top",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "@member thanks",
      parentId: top.id,
      mentionedUserIds: [],
    });

    expect(await alertKinds(tenant.userIds.member, issue.id)).toEqual(["comment_mention"]);
    expect(await alertKinds(tenant.userIds.owner, issue.id)).toEqual(["comment_created"]);
    expect(await alertKinds(tenant.userIds.admin, issue.id)).toEqual([]);
  });

  it("alerts the answered author of a plain reply", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Plain reply" }),
    );
    const top = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "top",
      parentId: null,
      mentionedUserIds: [],
    });
    await commentService.createComment(tenant.actors.admin, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "plain",
      parentId: top.id,
      mentionedUserIds: [],
    });
    expect(await alertKinds(tenant.userIds.member, issue.id)).toEqual(["comment_created"]);
  });
});

describe("scratch: edits", () => {
  it("alerts only newly mentioned people, records the new set, and reindexes", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Edits" }),
    );
    const comment = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id,
      issueId: issue.id,
      body: "first draft",
      parentId: null,
      mentionedUserIds: [],
    });

    await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "first draft cc @owner",
    });
    expect(await alertKinds(tenant.userIds.owner, issue.id)).toEqual(
      ["comment_created", "comment_mention"],
    );

    const edited = await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "first draft cc @owner and @admin zanzibar",
    });
    expect(new Set(edited.mentionedUserIds)).toEqual(
      new Set([tenant.userIds.owner, tenant.userIds.admin]),
    );
    expect(await alertKinds(tenant.userIds.owner, issue.id)).toEqual(
      ["comment_created", "comment_mention"],
    );
    expect(await alertKinds(tenant.userIds.admin, issue.id)).toEqual(["comment_mention"]);

    const hits = await searchService.search(tenant.actors.member, {
      orgId: tenant.org.id,
      q: "zanzibar",
      kinds: ["comment"],
      limit: 25,
      cursor: null,
    });
    expect(hits.items.map((h) => h.id)).toContain(comment.id);

    // Dropping a mention from the text removes it from the recorded list.
    const dropped = await commentService.updateComment(tenant.actors.member, {
      orgId: tenant.org.id,
      commentId: comment.id,
      body: "no names now",
    });
    expect(dropped.mentionedUserIds).toEqual([]);
  });

  it("counts the edit window from posting, not from the last edit", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    try {
      vi.setSystemTime(new Date("2026-02-01T00:00:00.000Z"));
      const issue = await issueService.createIssue(
        tenant.actors.owner,
        issueInput(tenant.org.id, tenant.project.id, { title: "Window" }),
      );
      const comment = await commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id,
        issueId: issue.id,
        body: "window",
        parentId: null,
        mentionedUserIds: [],
      });

      vi.setSystemTime(new Date("2026-02-01T00:10:00.000Z"));
      await commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "window 2",
      });
      vi.setSystemTime(new Date("2026-02-01T00:14:00.000Z"));
      await commentService.updateComment(tenant.actors.member, {
        orgId: tenant.org.id,
        commentId: comment.id,
        body: "window 3",
      });
      vi.setSystemTime(new Date("2026-02-01T00:16:00.000Z"));
      await expect(
        commentService.updateComment(tenant.actors.member, {
          orgId: tenant.org.id,
          commentId: comment.id,
          body: "too late",
        }),
      ).rejects.toThrow(/edit window/);

      // A moderator is not bound by the window.
      await expect(
        commentService.updateComment(tenant.actors.owner, {
          orgId: tenant.org.id,
          commentId: comment.id,
          body: "moderated",
        }),
      ).resolves.toMatchObject({ body: "moderated" });
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("scratch: thread", () => {
  it("keeps reply-to-reply in the thread and placeholders for deleted comments", async () => {
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "Thread shape" }),
    );
    const orgId = tenant.org.id;
    const top = await commentService.createComment(tenant.actors.member, {
      orgId, issueId: issue.id, body: "T", parentId: null, mentionedUserIds: [],
    });
    const r1 = await commentService.createComment(tenant.actors.admin, {
      orgId, issueId: issue.id, body: "R1", parentId: top.id, mentionedUserIds: [],
    });
    const r2 = await commentService.createComment(tenant.actors.owner, {
      orgId, issueId: issue.id, body: "R2", parentId: r1.id, mentionedUserIds: [],
    });
    const r3 = await commentService.createComment(tenant.actors.member, {
      orgId, issueId: issue.id, body: "R3", parentId: r2.id, mentionedUserIds: [],
    });
    const r4 = await commentService.createComment(tenant.actors.admin, {
      orgId, issueId: issue.id, body: "R4", parentId: top.id, mentionedUserIds: [],
    });

    let thread = await commentService.getThread(tenant.actors.member, orgId, issue.id);
    expect(thread).toHaveLength(1);
    expect(thread[0]?.replies.map((r) => r.id)).toEqual([r1.id, r2.id, r3.id, r4.id]);
    expect(await commentRepo.countComments(orgId, issue.id)).toBe(5);

    await commentService.deleteComment(tenant.actors.admin, { orgId, commentId: r1.id });
    thread = await commentService.getThread(tenant.actors.member, orgId, issue.id);
    expect(thread[0]?.replies.map((r) => r.id)).toEqual([r1.id, r2.id, r3.id, r4.id]);
    expect(thread[0]?.replies[0]?.body).toBe("");
    expect(thread[0]?.replies[0]?.archivedAt).not.toBeNull();
    expect(await commentRepo.countComments(orgId, issue.id)).toBe(4);

    await commentService.deleteComment(tenant.actors.member, { orgId, commentId: top.id });
    thread = await commentService.getThread(tenant.actors.member, orgId, issue.id);
    expect(thread).toHaveLength(1);
    expect(thread[0]?.comment.body).toBe("");
    expect(thread[0]?.comment.archivedAt).not.toBeNull();
    expect(thread[0]?.replies.map((r) => r.id)).toEqual([r1.id, r2.id, r3.id, r4.id]);
    expect(await commentRepo.countComments(orgId, issue.id)).toBe(3);
  });

  it("rejects a reply to a comment on another issue", async () => {
    const a = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "A" }),
    );
    const b = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { title: "B" }),
    );
    const onA = await commentService.createComment(tenant.actors.member, {
      orgId: tenant.org.id, issueId: a.id, body: "on A", parentId: null, mentionedUserIds: [],
    });
    await expect(
      commentService.createComment(tenant.actors.member, {
        orgId: tenant.org.id, issueId: b.id, body: "wrong", parentId: onA.id, mentionedUserIds: [],
      }),
    ).rejects.toThrow(/not found/i);
  });
});

describe("scratch: rate limit", () => {
  it("charges each member's burst to that member alone", async () => {
    let denied = false;
    for (let i = 0; i < 1000 && !denied; i += 1) {
      const verdict = await consumeRateLimit(tenant.org.id, "comment:create", 1, tenant.userIds.viewer);
      denied = !verdict.allowed;
    }
    expect(denied).toBe(true);
    const admin = await consumeRateLimit(tenant.org.id, "comment:create", 1, tenant.userIds.admin);
    expect(admin.allowed).toBe(true);
  });
});

